            "completionCriterion": "All four quantities are computed and checked against the series rules; any incorrect step is identified with the specific rule that was misapplied.",
            "effort": {
              "lowMinutes": 20,
              "likelyMinutes": 30,
              "highMinutes": 45
            },
            "timeboxMinutes": 30,
            "commitment": {
              "category": "COMMITTED"
            },
            "hardDependencies": []
          },
