{
  "decision": "REVISE",
  "detail": {
    "days": 14,
    "checkpoint": "Stop once the three assigned equations are solved, each expansion of a negative over parentheses is explained correctly, and every answer is verified by substitution."
  },
  "plans": [
    {
      "planRef": "plan_1",
      "blueprint": {
        "schemaVersion": 2,
        "strategy": {
          "policy": "GENERAL",
          "outcome": "Complete and understand a short homework set of three linear equations with parentheses. I make sign errors when expanding negatives.",
          "explanation": "The accepted outcome is a specific short assignment, so the smallest useful strategy is one integrated work session: the learner expands each parenthesised expression while stating the sign rule aloud, solves the three equations, and checks each answer by substitution. The reported weakness (sign errors when expanding negatives) is addressed inside the assignment itself rather than through a separate synthetic exercise. No readiness evidence exists, but the task is short and self-contained, so a single supported pass with an independent check on the actual assigned equations is sufficient; further practice is left optional or triggered only by an observed error.",
          "recommendedEffort": {
            "lowMinutes": 25,
            "likelyMinutes": 35,
            "highMinutes": 50
          },
          "phases": [
            {
              "localId": "phase_work",
              "title": "Complete and check the assigned equations",
              "outcome": "All three assigned linear equations with parentheses are solved, the negative-expansion sign rule is explained during the work, and every answer is verified by substitution.",
              "effort": {
                "lowMinutes": 25,
                "likelyMinutes": 35,
                "highMinutes": 50
              },
              "readinessCriterion": "The learner can expand a negative over parentheses correctly, solve each of the three assigned equations, and confirm each solution by substitution without prompting."
            }
          ]
        },
        "scope": [
          {
            "scopeRef": "scope_1",
            "disposition": "INCLUDED",
            "contribution": "The sign rule for distributing a negative over parentheses is explained and applied while expanding each assigned equation."
          },
          {
            "scopeRef": "scope_2",
            "disposition": "INCLUDED",
            "contribution": "The three assigned linear equations are solved and each solution is verified by substitution."
          }
        ],
        "activities": [
          {
            "localId": "homework_set",
            "outcomeRefs": [
              "phase_work"
            ],
            "scopeRefs": [
              "scope_1",
              "scope_2"
            ],
            "title": "Solve and check the three assigned linear equations with parentheses",
            "activityType": "Guided assignment completion",
            "purpose": "Complete the actual homework set while correcting the reported negative-expansion sign errors in the assigned work itself.",
            "instructions": "Work through the three assigned linear equations in order. For each equation: (1) before expanding, say or write the rule for distributing a negative over parentheses, e.g. -（a + b) = -a - b; (2) expand the parentheses, explicitly writing the sign of every term; (3) solve for the variable; (4) substitute your answer back into the original equation and confirm both sides are equal. If a sign error appears, correct it on the spot and note which term changed sign. Do not add extra equations beyond the three assigned unless an error shows a rule is still unclear.",
            "completionCriterion": "All three assigned equations are solved with correct expansions, and each solution is verified by substitution showing both sides equal.",
            "effort": {
              "lowMinutes": 25,
              "likelyMinutes": 35,
              "highMinutes": 50
            },
            "timeboxMinutes": 40,
            "commitment": {
              "category": "COMMITTED"
            },
            "hardDependencies": []
          },
          {
            "localId": "extra_sign_practice",
            "outcomeRefs": [
              "phase_work"
            ],
            "scopeRefs": [
              "scope_1"
            ],
            "title": "Optional extra negative-expansion practice",
            "activityType": "Optional practice",
            "purpose": "Provide additional sign-rule practice only if the learner wants more confidence after the assigned set.",
            "instructions": "If desired, expand and simplify five expressions of the form -(2x - 3) + 4x and check each by substituting a value for x. This is not required to complete the assignment.",
            "completionCriterion": "Five expressions expanded correctly with substitution checks.",
            "effort": {
              "lowMinutes": 10,
              "likelyMinutes": 15,
              "highMinutes": 20
            },
            "timeboxMinutes": 20,
            "commitment": {
              "category": "OPTIONAL",
              "reason": "The assigned set already provides evidence of the sign rule; extra practice is useful only if the learner wants more confidence and is not needed to meet the outcome."
            },
            "hardDependencies": []
          },
          {
            "localId": "remediation_sign_errors",
            "outcomeRefs": [
              "phase_work"
            ],
            "scopeRefs": [
              "scope_1"
            ],
            "title": "Targeted remediation if sign errors persist",
            "activityType": "Contingent remediation",
            "purpose": "Address a concrete observed failure in negative expansion with focused re-teaching and a small set of similar problems.",
            "instructions": "If, after completing the assigned set, the learner still makes sign errors when expanding a negative over parentheses, re-explain the rule with two contrasting examples (one where the negative distributes correctly, one where it is missed), then work through three new similar expansions together and have the learner do two independently.",
            "completionCriterion": "The learner correctly expands three new negative-over-parentheses expressions and explains the sign of each term.",
            "effort": {
              "lowMinutes": 15,
              "likelyMinutes": 20,
              "highMinutes": 30
            },
            "timeboxMinutes": 30,
            "commitment": {
              "category": "CONTINGENT",
              "trigger": {
                "checkpointActivityId": "homework_set",
                "condition": "The learner makes a sign error when expanding a negative over parentheses in any of the three assigned equations, even after self-correction."
              }
            },
            "hardDependencies": [
              "homework_set"
            ]
          }
        ],
        "decisions": {
          "assumptions": [
            "The three assigned equations are available to the learner and are of the form a(x + b) = c or similar with parentheses.",
            "The learner has already been taught how to solve basic linear equations without parentheses."
          ],
          "tradeOffs": [
            "No separate diagnostic or pre-teaching is scheduled because the assignment itself is short and the reported weakness can be addressed within it; this risks missing a deeper prerequisite gap, which is why a contingent remediation is provided."
          ],
          "unresolvedUncertainty": [
            "Whether the learner's sign errors come from the distributive rule itself or from later arithmetic steps; the integrated work and contingent remediation will reveal this."
          ],
          "stoppingConditions": [
            "Stop after the three assigned equations are solved, explained, and checked by substitution.",
            "Do not continue to optional or contingent work unless the learner chooses it or a concrete sign error triggers remediation."
          ]
        }
      }
    }
