          "assumptions": [
            "A supplied small CSV file with a header row and amount column is available for the task.",
            "The learner has basic Python syntax for variables, strings, and simple function calls, but is new to loops and dictionaries."
          ],
          "tradeOffs": [
            "The JSON report in plan_2 is not booked now; it remains strategic scope so the shared prerequisite can be taught once and demonstrated cleanly before adding a second output format.",
            "The first activity integrates explanation, application, and a changed example rather than separating them into multiple sessions, because the learner is a beginner and the CSV task is small enough to serve as the prerequisite checkpoint."
          ],
          "unresolvedUncertainty": [
            "The exact CSV column names and file source are not specified; the task assumes a simple amount column and category column.",
            "The learner's prior Python syntax fluency is unknown; if basic syntax blocks progress, the task may need to slow down, but no separate syntax unit is booked now."
          ],
          "stoppingConditions": [
            "Stop when the CSV totals report produces correct totals for the supplied file and a changed CSV example, and the learner can explain the loop and dictionary steps.",
            "Do not add a separate loops/dictionaries unit or a second full practice set unless the committed activity reveals a concrete failure that the integrated task did not resolve."
          ]
        }
      }
    },
