      "planRef": "plan_2",
      "blueprint": {
        "schemaVersion": 2,
        "strategy": {
          "policy": "ROADMAP",
          "outcome": "Build a JSON expenses report that totals expenses from supplied data, using the shared loops/dictionaries prerequisite owned by plan_1.",
