          "recommendedEffort": {
            "lowMinutes": 45,
            "likelyMinutes": 75,
            "highMinutes": 120
          },
          "phases": [
            {
              "localId": "json_report",
              "title": "JSON expenses report",
              "outcome": "A working JSON expenses report that reads supplied expense data, uses loops and dictionaries to total expenses, and writes a valid JSON result.",
              "effort": {
                "lowMinutes": 45,
                "likelyMinutes": 75,
                "highMinutes": 120
              },
              "readinessCriterion": "The learner can produce a valid JSON expenses report with correct totals after the shared loops/dictionaries prerequisite is demonstrated."
            }
          ]
        },
        "scope": [
          {
            "scopeRef": "scope_1",
            "disposition": "INCLUDED",
            "contribution": "Uses the shared loops/dictionaries prerequisite owned by plan_1; no duplicate instruction or activity is booked here."
          },
          {
            "scopeRef": "scope_2",
            "disposition": "INCLUDED",
            "contribution": "The JSON expenses report is the next strategic deliverable after the CSV checkpoint; it is not booked now to avoid duplicating the prerequisite and to keep the first checkpoint small."
          }
        ],
        "activities": [],
        "decisions": {
          "assumptions": [
            "The shared loops/dictionaries prerequisite will be demonstrated in plan_1 before JSON report work begins.",
            "The JSON report can reuse the same expense data structure and totals logic once the prerequisite is secure."
          ],
          "tradeOffs": [
            "No JSON report activity is committed in this window; the trade-off is that plan_2 progress waits on the plan_1 checkpoint, but this avoids duplicating the shared prerequisite and overloading a beginner.",
            "The JSON report remains strategic scope rather than being dropped; it can be detailed after the CSV checkpoint is independently demonstrated."
          ],
          "unresolvedUncertainty": [
            "The exact JSON schema for the expenses report is not specified; it will need to be defined when the JSON report is detailed.",
            "Whether the learner will need additional JSON syntax instruction is unknown; that will be assessed after the shared prerequisite checkpoint."
          ],
          "stoppingConditions": [
            "Do not book JSON report work until the plan_1 CSV totals checkpoint is demonstrated.",
            "When the JSON report is later detailed, stop once it produces valid JSON with correct totals and the learner can explain the loop and dictionary steps."
          ]
        }
      }
    }
  ],
  "sharedDependencies": [
    {
      "prerequisite": {
        "planRef": "plan_1",
        "activityId": "csv_totals_work"
      },
      "dependent": {
        "planRef": "plan_2",
        "activityId": "json_report"
      },
      "strength": "HARD",
      "reason": "The JSON expenses report depends on the same loops/dictionaries prerequisite taught and demonstrated in the CSV totals activity; plan_2 must not duplicate that instruction."
    }
  ],
  "tradeOffExplanation": "The shared loops/dictionaries prerequisite is owned once by plan_1 and taught through the CSV totals report, which is the first concrete deliverable. The JSON report in plan_2 is kept as strategic scope with no committed activity now, so the learner can demonstrate the prerequisite cleanly before adding a second output format. This avoids duplicating prerequisite work and keeps the first checkpoint small. The cost is that plan_2 progress waits on the plan_1 checkpoint, but that is educationally preferable to parallel beginner tasks competing for the same prerequisite."
}

